import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.Crpw6aS5.js";const k=JSON.parse('{"title":"安装指南","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/04-installation.md","filePath":"desktop/04-installation.md","lastUpdated":1783698470000}'),n={name:"desktop/04-installation.md"};function l(o,s,d,h,p,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="安装指南" tabindex="-1">安装指南 <a class="header-anchor" href="#安装指南" aria-label="Permalink to &quot;安装指南&quot;">​</a></h1><p>桌面端基于 <strong>Electron</strong>，提供 macOS / Windows / Linux 安装包。<code>v0.4.3</code> 起的正式 macOS Release 使用 Developer ID 签名和 notarization；更早版本或临时开发包仍可能需要手动放行。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><p>前往 <a href="https://github.com/LiuGuangHS/EchoFlow-ClaudeCode/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载对应平台的安装包：</p><table tabindex="0"><thead><tr><th>平台</th><th>文件</th></tr></thead><tbody><tr><td>macOS (Apple Silicon / M 系列)</td><td><code>EchoFlow-Code-&lt;版本&gt;-mac-arm64.dmg</code></td></tr><tr><td>macOS (Intel)</td><td><code>EchoFlow-Code-&lt;版本&gt;-mac-x64.dmg</code></td></tr><tr><td>Windows (x64)</td><td><code>EchoFlow-Code-&lt;版本&gt;-win-x64.exe</code></td></tr><tr><td>Windows (ARM64)</td><td><code>EchoFlow-Code-&lt;版本&gt;-win-arm64.exe</code></td></tr><tr><td>Linux (x64)</td><td><code>EchoFlow-Code-&lt;版本&gt;-linux-x86_64.AppImage</code> 或 <code>...-linux-amd64.deb</code></td></tr><tr><td>Linux (ARM64)</td><td><code>EchoFlow-Code-&lt;版本&gt;-linux-arm64.AppImage</code> 或 <code>...-linux-arm64.deb</code></td></tr></tbody></table><blockquote><p>不确定 Mac 架构？点击左上角 → 关于本机，芯片为「Apple M…」选 arm64，「Intel」选 x64。</p></blockquote><p>移动端 Android 客户端用于连接已经运行的桌面端或本地服务。它不会在手机上运行 sidecar，也不会替代桌面端安装；需要先在桌面端开启 H5 访问，再按 <a href="/mobile/">移动端文档</a> 扫码或手动输入 Server URL + H5 Token。</p><h2 id="macos-安装" tabindex="-1">macOS 安装 <a class="header-anchor" href="#macos-安装" aria-label="Permalink to &quot;macOS 安装&quot;">​</a></h2><p>双击 DMG 把应用拖入 <code>Applications</code>。<code>v0.4.3</code> 起的正式 Release 正常情况下只会出现 macOS 的标准下载来源确认，不需要执行 <code>xattr</code>。</p><p>如果安装的是旧版或 unsigned 临时包，首次打开可能提示**&quot;已损坏&quot;<strong>或</strong>&quot;无法验证开发者&quot;**，再在终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/EchoFlow Code.app&quot;</span></span></code></pre></div><p>也可以在「系统设置 → 隐私与安全性」里点&quot;仍要打开&quot;。</p><h2 id="windows-安装" tabindex="-1">Windows 安装 <a class="header-anchor" href="#windows-安装" aria-label="Permalink to &quot;Windows 安装&quot;">​</a></h2><p>双击 <code>.exe</code> 安装。首次运行如果 SmartScreen 弹出 <strong>&quot;Windows 已保护你的电脑&quot;</strong>，点击 <strong>「更多信息」</strong> → <strong>「仍要运行」</strong>。</p><h2 id="linux-安装" tabindex="-1">Linux 安装 <a class="header-anchor" href="#linux-安装" aria-label="Permalink to &quot;Linux 安装&quot;">​</a></h2><p>AppImage：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EchoFlow-Code-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">版</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">本</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-linux-x86_64.AppImage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./EchoFlow-Code-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;版本&gt;-linux-x86_64.AppImage</span></span></code></pre></div><blockquote><p>提示缺少 FUSE：Ubuntu 22.04 及更早 <code>sudo apt install libfuse2</code>，24.04+ <code>sudo apt install libfuse2t64</code>。</p></blockquote><p>deb：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./EchoFlow-Code-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">版</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">本</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-linux-amd64.deb</span></span></code></pre></div><h2 id="web-ui-模式" tabindex="-1">Web UI 模式 <a class="header-anchor" href="#web-ui-模式" aria-label="Permalink to &quot;Web UI 模式&quot;">​</a></h2><p>如果桌面端安装遇到问题，可以直接通过浏览器使用 Web UI。在项目根目录下分别启动服务端和前端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 启动服务端（在项目根目录）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SERVER_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3456</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/server/index.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 启动前端（在 desktop 目录）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2024</span></span></code></pre></div><p>启动后浏览器访问 <code>http://127.0.0.1:2024</code> 即可。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 这个版本会自动更新吗？</strong></p><p><code>v0.4.3</code> 起的正式 Release 会通过 GitHub Releases 检查更新，并下载对应平台的更新包。首次迁移到 signed/notarized macOS 版本时，建议先手动下载安装 <code>v0.4.3</code>；后续版本可以走应用内更新。Windows/macOS 系统仍可能要求你手动确认。</p><p>覆盖安装或应用内更新不会删除本地数据。Claude Code 兼容数据（例如 <code>projects</code>、<code>skills</code>、<code>plugins</code>, <code>agents</code>, <code>teams</code>, <code>tasks</code>, <code>adapters.json</code>）默认继续保存在 <code>~/.claude</code>；EchoFlow 自有 Provider、OAuth、桌面偏好和 diagnostics 保存在 EchoFlow 应用数据目录。macOS Release 优先使用签名和公证；缺少证书时会发布 unsigned fallback，需要运行随 Release 提供的 <code>install-macos-unsigned.sh</code> 或手动放行。Windows 签名不是发布阻塞项，未签名安装包仍可更新，但可能出现 SmartScreen 提示。最稳妥的方式仍是到 <a href="https://github.com/LiuGuangHS/EchoFlow-ClaudeCode/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> 下载最新版覆盖安装。</p>`,28)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
